from pathlib import Path
import json,html
p=Path(__file__).resolve().parent
posts=json.loads((p/'posts.json').read_text())
css='''@font-face{font-family:Nunito;src:url('assets/nunito-variable.ttf')}*{box-sizing:border-box}body{margin:0;background:#f4f7fc;color:#0b1b3a;font:17px Nunito,system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:38px 28px 80px}header{display:flex;justify-content:space-between;align-items:center;gap:20px}header img{width:150px}a{color:#0047ab}h1{font-size:clamp(38px,6vw,70px);letter-spacing:-2px;line-height:1.05;max-width:850px;margin:40px 0 20px}h2{font-size:32px;margin:0 0 18px}p{line-height:1.6}.intro{max-width:800px;font-size:21px;color:#435778}.pill{font-size:13px;font-weight:900;letter-spacing:1px;background:#e3ecfa;padding:10px 16px;border-radius:100px}.section{margin-top:56px}.cover{width:100%;display:block;border-radius:18px 18px 0 0}.fb{background:white;border:1px solid #dbe3f0;border-radius:20px;overflow:hidden}.profilebar{display:flex;gap:22px;align-items:center;padding:0 35px 25px}.avatar{width:126px;height:126px;border-radius:50%;border:6px solid white;margin-top:-28px;position:relative}.profilebar h3{font-size:32px;margin:12px 0 2px}.profilebar p{margin:0;color:#435778}.action,button{border:0;background:#0047ab;color:white;padding:12px 18px;border-radius:10px;font:800 15px Nunito,system-ui;cursor:pointer}.action{margin-left:auto;text-decoration:none}.note{color:#5a6b85;font-size:14px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:28px}.panel{background:white;padding:26px;border:1px solid #dbe3f0;border-radius:20px}.ighead{display:flex;gap:20px;align-items:center}.ighead img{width:85px;height:85px;border-radius:50%}.ighead h3{margin:0 0 8px;font-size:24px}.igbio{line-height:1.6}.highlights{display:flex;gap:18px;margin:24px 0}.highlights img{width:60px;height:60px;border-radius:50%;border:1px solid #dbe3f0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.grid img{width:100%;display:block}.placeholder{aspect-ratio:1;background:#e3ecfa;display:grid;place-items:center;text-align:center;font-size:13px;padding:8px;color:#435778}.platforms{display:flex;gap:10px;margin:20px 0}button[aria-pressed=false]{background:#e3ecfa;color:#0047ab}.posts{display:grid;grid-template-columns:1fr 1fr;gap:30px}.post{background:white;border:1px solid #dbe3f0;border-radius:20px;overflow:hidden}.post>img{width:100%;display:block}.postbody{padding:26px}.postbody h3{font-size:26px;margin:12px 0}.caption{white-space:pre-wrap;line-height:1.65;font-size:16px}.tools{display:flex;align-items:center;gap:18px;margin-top:22px}.schedule{display:grid;gap:16px}.slot{display:flex;gap:16px;border-bottom:1px solid #e3ecfa;padding-bottom:14px}.slot b{white-space:nowrap;color:#0047ab}.downloads{display:flex;gap:16px;flex-wrap:wrap}footer{margin-top:50px;color:#5a6b85}.status{min-height:24px;font-size:14px}[hidden]{display:none!important}@media(max-width:750px){.columns,.posts{grid-template-columns:1fr}.profilebar{padding:0 18px 20px;gap:12px}.avatar{width:85px;height:85px}.profilebar h3{font-size:24px}.action{display:none}header{align-items:flex-start}.pill{font-size:10px}main{padding:24px 16px}h1{letter-spacing:-1px}}'''
parts=[f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manotu · Social launch studio</title><style>{css}</style><main><header><img src="assets/manotu-wordmark.svg" alt="Manotu"><span class="pill">SOCIAL LAUNCH KIT · DRAFTS</span></header><h1>Ma’no tu?<br>Let’s meet the community.</h1><p class="intro">A Malay-first Facebook and Instagram identity for Manotu. Four useful opening posts. One familiar voice. Built around community, everyday places and privacy.</p><div class="downloads"><a href="plan.md">Page plan &amp; brand corrections</a><a href="posts.md">Copy-ready captions</a><a href="assets/profile.png" download>Profile image</a><a href="assets/facebook-cover.png" download>Facebook cover</a></div><section class="section"><h2>01 / Facebook page concept</h2><div class="fb"><img class="cover" src="assets/facebook-cover.png" alt="Manotu Facebook cover: Ma’no tu? Ke mana pun, bersama Manotu."><div class="profilebar"><img class="avatar" src="assets/profile.png" alt="Manotu wau profile icon"><div><h3>Manotu</h3><p>Navigasi komuniti Malaysia · Akses awal</p></div><a class="action" href="https://manotu.app/">Learn more</a></div></div><p class="note">Design preview, not a live account. Proposed handle @manotuapp; availability unverified. Cover master 1640 × 624; inspect the platform crop when uploading.</p></section><section class="section columns"><div><h2>02 / Instagram identity</h2><div class="panel"><div class="ighead"><img src="assets/profile.png" alt="Manotu icon"><div><h3>manotuapp</h3><strong>Manotu | Navigasi Malaysia</strong></div></div><p class="igbio">Navigasi komuniti Malaysia 🪁<br>Percuma · Tanpa iklan<br>Tempat peribadi kekal dalam telefon anda.<br>Akses awal ↓<br><a href="https://manotu.app/">manotu.app</a></p><div class="highlights">']
for i,label in enumerate(['Mula','Privasi','Cara guna','Komuniti'],1):parts.append(f'<a href="assets/highlight-0{i}.png" download><img src="assets/highlight-0{i}.png" alt="{label} highlight cover"></a>')
parts.append('</div><div class="grid">')
for post in posts:parts.append(f'<img src="assets/{post["id"]}.png" alt="{html.escape(post["title"])}">')
parts.append('<div class="placeholder">NEXT: Real app<br>how-to recording</div><div class="placeholder">NEXT: Community<br>place spotlight</div></div><p class="note">Grid direction only; the last two tiles are future content slots.</p></div></div><div><h2>03 / A measured first week</h2><div class="panel schedule">')
for post in posts:parts.append(f'<div class="slot"><b>{post["day"].split(" · ")[0]}</b><span>{post["title"]}<br><small>{post["day"].split(" · ")[1]}</small></span></div>')
parts.append('<p>Introduce the app. Start a light conversation. Explain one privacy promise. Invite a useful contribution.</p><p>These are launch-relative slots, not scheduled posts. Use real account insights to refine timing after launch.</p><p class="note">Public drafts use Manotu and manotu.app throughout. No invented follower counts, reviews or testimonials.</p></div></div></section><section class="section"><h2>04 / Four posts, ready to review</h2><p>Choose a platform to see its caption. The same square artwork works independently in either feed.</p><div class="platforms"><button id="fb" aria-pressed="true">Facebook copy</button><button id="ig" aria-pressed="false">Instagram copy</button></div><div class="posts">')
for post in posts:
 parts.append(f'<article class="post"><img src="assets/{post["id"]}.png" alt="{html.escape(post["alt"])}"><div class="postbody"><span class="pill">{post["day"]}</span><h3>{post["title"]}</h3><div class="caption fb">{html.escape(post["facebook"])}</div><div class="caption ig" hidden>{html.escape(post["instagram"])}</div><div class="tools"><button class="copy">Copy caption</button><a href="assets/{post["id"]}.png" download>Download PNG</a><a href="assets/{post["id"]}.svg" download>SVG</a></div><p class="status" role="status"></p></div></article>')
parts.append('''</div></section><footer>Prepared 26 October 2026 · New page concepts and post drafts only. No posts published.<br>Manotu-authored code is MIT licensed; Google and Apple platform dependencies are disclosed in the repository.</footer></main><script>
let platform='fb';
for(const id of ['fb','ig']) document.getElementById(id).onclick=()=>{platform=id;for(const key of ['fb','ig']){document.getElementById(key).setAttribute('aria-pressed',String(key===id));document.querySelectorAll('.caption.'+key).forEach(e=>e.hidden=key!==id);}};
document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{const card=b.closest('.post');try{await navigator.clipboard.writeText(card.querySelector('.caption.'+platform).textContent);card.querySelector('.status').textContent='Caption copied.';}catch{card.querySelector('.status').textContent='Select and copy the caption above.';}});
</script></html>''')
(p/'index.html').write_text(''.join(parts))
md=['# Manotu · Launch post captions\n\nDrafts only. No posts published.\n']
for post in posts:
 md += [f'## {post["day"]}: {post["title"]}\n',f'![{post["alt"]}](assets/{post["id"]}.png)\n','### Facebook\n',post['facebook']+'\n','### Instagram\n',post['instagram']+'\n',f'Alt text: {post["alt"]}\n']
(p/'posts.md').write_text('\n'.join(md))
